<script setup>
import { computed,onMounted,reactive,ref } from 'vue';import { useRoute } from 'vue-router';import { ElMessage,ElMessageBox } from 'element-plus';import http from '../api/http';import { useAuthStore } from '../stores/auth';import { dateText,statusText } from '../utils/format';import { assetUrl } from '../utils/url'
const route=useRoute(),auth=useAuthStore(),data=ref(null),loading=ref(false),completionVisible=ref(false),reviewVisible=ref(false),form=reactive({description:'',proofUrl:''}),review=reactive({rating:5,content:''});const order=computed(()=>data.value?.order),isPublisher=computed(()=>auth.user?.id===order.value?.publisherId),isAccepter=computed(()=>auth.user?.id===order.value?.accepterId);async function load(){data.value=await http.get(`/api/orders/${route.params.id}`)}async function action(name,body={}){loading.value=true;try{data.value=await http.post(`/api/orders/${route.params.id}/${name}`,body);ElMessage.success('操作成功')}catch(e){ElMessage.error(e.message)}finally{loading.value=false}}async function upload(option){const fd=new FormData();fd.append('file',option.file);try{const result=await http.post('/api/files/images',fd);form.proofUrl=result.url;option.onSuccess(result);ElMessage.success('凭证已上传')}catch(e){option.onError(e)}}async function submit(){await action('completions',form);completionVisible.value=false}async function reject(){const {value}=await ElMessageBox.prompt('请说明需要补充或修改的内容','驳回结果',{inputType:'textarea',inputValidator:v=>v?.length>2||'请填写原因'});await action('reject',{reason:value})}async function abnormal(){const {value}=await ElMessageBox.prompt('请描述异常或争议','发起异常处理',{inputType:'textarea',inputValidator:v=>v?.length>3||'请填写说明'});try{await http.post(`/api/tasks/${data.value.task.id}/abnormal`,{reasonType:'DISPUTE',description:value});ElMessage.success('已提交管理员处理');load()}catch(e){ElMessage.error(e.message)}}async function submitReview(){const other=isPublisher.value?data.value.accepter:data.value.publisher;try{await http.post('/api/reviews',{businessType:'TASK',businessId:order.value.id,revieweeId:other.id,...review});ElMessage.success('评价已提交');reviewVisible.value=false}catch(e){ElMessage.error(e.message)}}onMounted(load)
</script>
<template><div v-if="data"><div class="page-head"><div><p>任务履约 #{{order.id}}</p><h1>{{data.task.title}}</h1></div><span class="status-pill">{{statusText(order.status)}}</span></div><div class="two-col"><section class="surface panel"><h3 class="panel-title">履约进度</h3><el-steps direction="vertical" :active="['WAIT_EXECUTE','IN_PROGRESS','WAIT_ACCEPTANCE','COMPLETED'].indexOf(order.status)+1" finish-status="success"><el-step title="确认接取" :description="dateText(order.acceptedAt)"/><el-step title="开始执行" :description="dateText(order.startedAt)"/><el-step title="提交并验收" :description="order.status==='WAIT_ACCEPTANCE'?'等待发布者确认':'提交后由发布者验收'"/><el-step title="完成结算" :description="dateText(order.completedAt)"/></el-steps><div class="action-row" style="margin-top:20px"><el-button v-if="isAccepter&&order.status==='WAIT_EXECUTE'" type="primary" :loading="loading" @click="action('start')">开始任务</el-button><el-button v-if="isAccepter&&order.status==='IN_PROGRESS'" type="primary" @click="completionVisible=true">提交完成结果</el-button><template v-if="isPublisher&&order.status==='WAIT_ACCEPTANCE'"><el-button type="success" :loading="loading" @click="action('approve')">验收通过</el-button><el-button type="danger" plain @click="reject">驳回重提</el-button></template><el-button v-if="['IN_PROGRESS','WAIT_ACCEPTANCE'].includes(order.status)" type="warning" plain @click="abnormal">异常处理</el-button><el-button v-if="order.status==='COMPLETED'" @click="reviewVisible=true">评价对方</el-button></div></section><aside class="section-stack"><section class="surface panel"><h3 class="panel-title">任务双方</h3><p><strong>发布者：</strong>{{data.publisher.nickname}} <span class="muted">信用 {{data.publisher.creditScore}}</span></p><p><strong>接取者：</strong>{{data.accepter.nickname}} <span class="muted">信用 {{data.accepter.creditScore}}</span></p><p><strong>奖励：</strong><span class="points">{{data.task.rewardPoints}}</span> 积分</p></section><section class="surface panel"><h3 class="panel-title">完成记录</h3><div v-for="c in data.completions" :key="c.id" class="list-card" style="background:#f5f7f3"><div><el-tag size="small">{{statusText(c.reviewStatus)}}</el-tag><span class="muted" style="margin-left:8px">{{dateText(c.submitTime)}}</span></div><p>{{c.description}}</p><el-image v-if="c.proofUrl" :src="assetUrl(c.proofUrl)" fit="cover" style="width:100%;height:150px;border-radius:10px" :preview-src-list="[assetUrl(c.proofUrl)]"/><p v-if="c.rejectReason" style="color:#b54b4b">驳回原因：{{c.rejectReason}}</p></div><div v-if="!data.completions.length" class="muted">暂无提交记录</div></section></aside></div><el-dialog v-model="completionVisible" title="提交完成结果" width="520"><el-form label-position="top"><el-form-item label="完成说明"><el-input v-model="form.description" type="textarea" :rows="4"/></el-form-item><el-form-item label="图片凭证"><el-upload :http-request="upload" :show-file-list="false" accept="image/*"><el-button>选择并上传图片</el-button></el-upload><el-image v-if="form.proofUrl" :src="assetUrl(form.proofUrl)" style="width:120px;height:90px;margin-top:10px;border-radius:8px" fit="cover"/></el-form-item></el-form><template #footer><el-button @click="completionVisible=false">取消</el-button><el-button type="primary" :loading="loading" @click="submit">提交验收</el-button></template></el-dialog><el-dialog v-model="reviewVisible" title="评价本次合作" width="460"><el-form label-position="top"><el-form-item label="星级"><el-rate v-model="review.rating"/></el-form-item><el-form-item label="评价内容"><el-input v-model="review.content" type="textarea" :rows="4"/></el-form-item></el-form><template #footer><el-button @click="reviewVisible=false">取消</el-button><el-button type="primary" @click="submitReview">提交评价</el-button></template></el-dialog></div></template>
